        "tags": [
          "Adams National Historical Park",
          "Abigail Adams",
          "John Adams",
          "John Quincy Adams",
          "John Quincy Adams Birthplace",
          "Adams Farm at Penns Hill",
          "American Revolution",
          "Semiquincentennial",
          "250th Anniversary",
          "america 250",
          "Battle of Bunker Hill"
        ],
        "location": "",
