    {
      "name": "Cane River Creole National Historical Park",
      "code": "cari",
      "description": "The Cane River region is home to a unique culture; the Creoles. Generations of the same families of workers, enslaved and tenant, and owners lived on these lands for over 200 years. The park tells their stories and preserves the cultural landscape of Oakland and Magnolia Plantations, two of the most intact Creole cotton plantations in the United States.",
      "states": [
        "LA"
      ],
      "url": "https://www.nps.gov/cari/index.htm",
      "designation": "National Historical Park",
      "activities": [
        "Arts and Culture",
        "Food",
        "Picnicking",
        "Guided Tours",
        "Self-Guided Tours - Walking",
        "Junior Ranger Program"
      ],
      "weatherInfo": "Weather in central Louisiana can be unpredictable. Summers are hot and humid. Winter is relatively mild with measurable snowfall every 5-10 years. Average rainfall is approximately 55-60 inches per year. The area is also subject to severe thunderstorms, hail, damaging winds, and tornadoes. Visitors might want to bring hats, umbrellas, and drink plenty of water. Please check the local weather forecast before planning your visit to the park.",
      "location": {
        "latitude": "31.65408447",
        "longitude": "-93.00131977"
      },
      "entranceFees": [],
      "operatingHours": [
        {
          "name": "Oakland and Magnolia Plantations",
          "description": "The Texas & Pacific Railway Depot, Oakland Plantation and Magnolia Plantation are open Wednesday through Sunday from 9 am to 3:30 pm. Both self-guided and guided tours of the plantation grounds and outbuildings are available. In addition, the park store located in the Oakland Plantation store is open for shopping. The Oakland Plantation Main House is open for self-guided tours only on Saturday and Sunday from 10 a.m. to 2 p.m. Closed all federal holidays.",
          "standardHours": {
            "wednesday": "9:00AM - 3:30PM",
            "monday": "Closed",
            "thursday": "9:00AM - 3:30PM",
