  "parks": [
    {
      "name": "Butterfield Overland National Historic Trail",
      "code": "buov",
      "description": "In 1857, businessman and transportation entrepreneur John Butterfield was awarded a contract to establish an overland mail route between the eastern United States and growing populations in the Far West. What became known as the Butterfield Overland Trail made an arcing sweep across the southern rim of the country. Stagecoaches left twice a week carrying passengers, freight, and mail.",
      "states": [
        "MO",
        "AR",
        "OK",
        "TX",
        "NM",
        "AZ",
        "CA"
      ],
      "url": "https://www.nps.gov/buov/index.htm",
      "designation": "National Historic Trail",
      "activities": [],
      "weatherInfo": "Due to the length of the trail, be sure to consult local weather sources for the region you'll be visiting. Check out the forecast with the National Weather Service and search for the area you'd like to visit: weather.gov",
      "location": {
        "latitude": "32.2768237589",
        "longitude": "-106.796583304"
      },
      "entranceFees": [],
      "operatingHours": [
        {
          "name": "Butterfield Overland National Historic Trail",
          "description": "The Butterfield Overland National Historic Trail is not a clearly marked hiking trail. Instead, it is a corridor that passes through communities, urban areas, public lands, and Wilderness. The route travels across a variety of land ownerships and management, including private land. Each location varies as to the hours of operation and access. Please contact individual trail sites before your visit for more information.",
          "standardHours": {
            "wednesday": "All Day",
            "monday": "All Day",
            "thursday": "All Day",
            "sunday": "All Day",
            "tuesday": "All Day",
            "friday": "All Day",
            "saturday": "All Day"
          }
        }
      ],
      "contacts": {
        "phoneNumbers": [
          {
            "type": "Voice",
            "number": "N/A",
            "description": ""
          }
        ],
        "emailAddresses": [
          {
            "address": "ntir_information@nps.gov",
            "description": ""
          }
        ]
      },
      "images": [
        {
          "url": "https://www.nps.gov/common/uploads/structured_data/9FE3B918-08B8-B25B-1BDD48E090045099.jpg",
          "title": "Presidio Chapel of San Elizario",
          "altText": "A cross and bell on the roof alcove of a white stucco church.",
          "caption": "A site along the Butterfield Overland National Historic Trail",
          "credit": "NPS Photo"
        },
        {
          "url": "https://www.nps.gov/common/uploads/structured_data/A0402204-FBD7-DC23-F626D64AEE7FE482.jpg",
          "title": "Old Pinery Butterfield Overland NHT",
          "altText": "A historic stone wall stands in ruins next to a hiking trail leading into the Guadalupe Mountains NP",
          "caption": "Visit the Butterfield Overland National Historic Trail to a take a step back in time.",
          "credit": "NPS Photo"
        },
        {
          "url": "https://www.nps.gov/common/uploads/structured_data/A08BBA41-FBAC-9ED1-EDD0A32E39B8278A.jpg",
          "title": "Saguaro Forest on the Butterfield Overland NHT",
          "altText": "A forest of tall, multi-armed Saguaro cacti stretches out towards the horizon.",
          "caption": "The Butterfield Overland NHT traversed thousands of miles of desert on the delivery route.",
          "credit": "NPS Photo"
        },
        {
          "url": "https://www.nps.gov/common/uploads/structured_data/A0C65CB2-B5B4-2A05-B674624D23E692C8.jpg",
          "title": "Butterfield Station site at Picacho Village in Dona Ana County, NM",
          "altText": "A neighborhood street lined with single story ranch homes.",
          "caption": "The Butterfield Overland NHT passes through modern city neighborhoods.",
          "credit": "NPS Photo"
        },
        {
          "url": "https://www.nps.gov/common/uploads/structured_data/A0FB2B66-B108-1BEB-CB3FB20958D8CF8F.jpg",
          "title": "El Paso Station Marker",
          "altText": "A large stone monument sits on the side of a historic city street with brick buildings.",
          "caption": "Historic El Paso, Texas offers an opportunity to visit the trail in a busy city.",
          "credit": "NPS Photo"
        }
      ]
    },
    {
      "name": "Castle Mountains National Monument",
      "code": "camo",
      "description": "Castle Mountains represents some of the most unique elements of the Mojave Desert. Nestled between the Nevada state line and Mojave National Preserve, the nearly 21,000 acres of Castle Mountains boasts Joshua tree forests, unbroken natural landscapes, rare desert grasslands, and rich human history. This intriguing area provides serenity and solitude from nearby metropolitan areas.",
      "states": [
        "CA"
      ],
      "url": "https://www.nps.gov/camo/index.htm",
      "designation": "National Monument",
      "activities": [
        "Camping",
        "Car or Front Country Camping",
        "Group Camping",
