    {
      "name": "Dickey Ridge Visitor Center",
      "parkCode": "shen",
      "description": "Dickey Ridge Visitor Center (mile 4.6) is located near Front Royal, Virginia, in the northern part of the Park. It's the ideal place for visitors entering through the Front Royal Entrance Station to find restrooms, information, a bookstore, publications, and maps. Right across Skyline Drive from the visitor center you will find the popular Fox Hollow Trail trailhead.",
      "url": "",
      "directionsInfo": "From Washington, D.C. metro area, travel west on Interstate 66 to Front Royal, Virginia (62 miles). Take the exit onto Route 340 South and follow signs for Shenandoah National Park and Skyline Drive, which will lead you to the Front Royal Entrance Station . Once on Skyline Drive, make your way south to mile marker 4.6; you will find Dickey Ridge Visitor Center on your right.",
      "directionsUrl": "http://www.nps.gov/shen/planyourvisit/directions.htm",
      "location": {
        "latitude": "38.87172417347",
        "longitude": "-78.20465862785",
        "address": {
          "line1": "17065 Skyline Drive",
          "line2": "",
          "city": "Front Royal",
          "stateCode": "VA",
          "postalCode": "22630"
        }
      },
      "operatingHours": [
        {
          "name": "Dickey Ridge Visitor Center",
          "description": "Park Rangers will staff the visitor center during operating hours to answer questions and provide tips for your visit. Restrooms are available year-round.",
